const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const to = [], cap = [], adj = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < m; i++) {
  const u = tok[2 + 3 * i], v = tok[3 + 3 * i], c = tok[4 + 3 * i];
  adj[u].push(to.length); to.push(v); cap.push(c);
  adj[v].push(to.length); to.push(u); cap.push(0);
}
const s = 1, t = n;
let flow = 0, level, it;
function dfs(v, f) {
  if (v === t) return f;
  while (it[v] < adj[v].length) {
    const e = adj[v][it[v]];
    if (cap[e] > 0 && level[to[e]] === level[v] + 1) {
      const d = dfs(to[e], Math.min(f, cap[e]));
      if (d > 0) { cap[e] -= d; cap[e ^ 1] += d; return d; }
    }
    it[v]++;
  }
  return 0;
}
for (;;) {
  level = new Array(n + 1).fill(-1);
  level[s] = 0;
  const q = [s];
  for (let h = 0; h < q.length; h++) {
    const v = q[h];
    for (const e of adj[v]) if (cap[e] > 0 && level[to[e]] < 0) { level[to[e]] = level[v] + 1; q.push(to[e]); }
  }
  if (level[t] < 0) break;
  it = new Array(n + 1).fill(0);
  for (;;) {
    const f = dfs(s, 1e18);
    if (f === 0) break;
    flow += f;
  }
}
