import java.io.*;
import java.util.*;

public class Main {
    static int n, t;
    static int[] to, level, it;
    static long[] cap;
    static List<Integer>[] adj;

    static long dfs(int v, long f) {
        if (v == t) return f;
        for (; it[v] < adj[v].size(); it[v]++) {
            int e = adj[v].get(it[v]);
            if (cap[e] > 0 && level[to[e]] == level[v] + 1) {
                long d = dfs(to[e], Math.min(f, cap[e]));
                if (d > 0) { cap[e] -= d; cap[e ^ 1] += d; return d; }
            }
        }
        return 0;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        to = new int[2 * m];
        cap = new long[2 * m];
        adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            in.nextToken();
            int u = (int) in.nval;
            in.nextToken();
            int v = (int) in.nval;
            in.nextToken();
            long c = (long) in.nval;
            adj[u].add(2 * i); to[2 * i] = v; cap[2 * i] = c;
            adj[v].add(2 * i + 1); to[2 * i + 1] = u;
        }
        int s = 1;
        t = n;
        long flow = 0;
        level = new int[n + 1];
        while (true) {
            Arrays.fill(level, -1);
            level[s] = 0;
            ArrayDeque<Integer> q = new ArrayDeque<>();
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int e : adj[v]) if (cap[e] > 0 && level[to[e]] < 0) { level[to[e]] = level[v] + 1; q.add(to[e]); }
            }
            if (level[t] < 0) break;
            it = new int[n + 1];
            long f;
            while ((f = dfs(s, Long.MAX_VALUE)) > 0) flow += f;
        }
        System.out.println(flow);
    }
}

