#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n, t;
vector<int> to, level_, it_;
vector<ll> cap;
vector<vector<int>> adj;

ll dfs(int v, ll f) {
    if (v == t) return f;
    for (; it_[v] < (int)adj[v].size(); it_[v]++) {
        int e = adj[v][it_[v]];
        if (cap[e] > 0 && level_[to[e]] == level_[v] + 1) {
            ll d = dfs(to[e], min(f, cap[e]));
            if (d > 0) { cap[e] -= d; cap[e ^ 1] += d; return d; }
        }
    }
    return 0;
}

int main() {
    int m;
    scanf("%d %d", &n, &m);
    adj.assign(n + 1, {});
    for (int i = 0; i < m; i++) {
        int u, v;
        ll c;
        scanf("%d %d %lld", &u, &v, &c);
        adj[u].push_back(to.size()); to.push_back(v); cap.push_back(c);
        adj[v].push_back(to.size()); to.push_back(u); cap.push_back(0);
    }
    int s = 1;
    t = n;
    ll flow = 0;
    while (true) {
        level_.assign(n + 1, -1);
        level_[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int e : adj[v]) if (cap[e] > 0 && level_[to[e]] < 0) { level_[to[e]] = level_[v] + 1; q.push(to[e]); }
        }
        if (level_[t] < 0) break;
        it_.assign(n + 1, 0);
        ll f;
        while ((f = dfs(s, LLONG_MAX)) > 0) flow += f;
    }
    printf("%lld\n", flow);
    return 0;
}
